package com.ecommerce.cart.service;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.web.client.*; import org.springframework.web.server.ResponseStatusException; import com.fasterxml.jackson.databind.JsonNode;
@Service public class ProductClient {private final RestClient client;private final String url;public ProductClient(RestClient.Builder b,@Value("${app.product.url}")String u){client=b.build();url=u.replaceAll("/+$","");}public JsonNode get(String id){try{return client.get().uri(url+"/api/products/{id}",id).retrieve().body(JsonNode.class);}catch(HttpClientErrorException.NotFound e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found");}catch(RestClientException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Product service unavailable",e);}}}